$string['bmc_hint_segments_purpose'] = 'Для кого компания создаёт ценность и какие сегменты являются приоритетными.';
$string['bmc_hint_segments_questions'] = 'Кто платит, кто принимает решение и пользуется; какая проблема/цель у клиента; какие сегменты дают выручку, маржу, рост или стратегическую ценность; есть ли опасная концентрация.';
$string['bmc_hint_segments_mistake'] = 'Писать «все компании» или «все люди» без сегмента и критериев выбора.';
