$string['bmc_hint_valueprop_questions'] = 'Клиент + проблема/цель + результат + отличие; продукт, сервис, бренд, персонал и цена/экономика клиента как единый пакет ценности.';
$string['bmc_hint_valueprop_mistake'] = 'Перечислять характеристики продукта вместо результата клиента и причины выбора.';
$string['bmc_hint_relationships_purpose'] = 'Как компания привлекает, продаёт, сопровождает, удерживает, возвращает и развивает клиента.';
$string['bmc_hint_relationships_questions'] = 'Как выглядит реальный клиентский цикл; где определены владельцы, уровни сервиса, регулярные обзоры и правила эскалации; что должно стать устойчивой нормой.';
$string['bmc_hint_relationships_mistake'] = 'Смешивать взаимодействие с каналом: канал — «через что», взаимодействие — «как строятся отношения и цикл работы».';
$string['bmc_hint_channels_purpose'] = 'Через какие собственные и партнёрские каналы клиент узнаёт о компании, приходит, покупает и получает ценность.';
$string['bmc_hint_channels_questions'] = 'Какие каналы реально дают спрос и продажи; какой вклад дают в выручку/маржу; какие должны стать воспроизводимыми и масштабируемыми.';
$string['bmc_hint_channels_mistake'] = 'Считать любой маркетинговый инструмент отдельным каналом без понимания его роли в цепочке спроса, продажи и поставки ценности.';
$string['bmc_hint_activities_purpose'] = 'Какие виды деятельности критичны для создания обещанной ценности и работы именно этой бизнес-модели.';
$string['bmc_hint_activities_questions'] = 'Продукт/услуга, маркетинг/продажи, доставка/сервис, управление и развитие; какие способности действительно критичны.';
$string['bmc_hint_activities_mistake'] = 'Перечислять все функции организации вместо ключевых способностей конкретной бизнес-модели.';
$string['bmc_hint_resources_purpose'] = 'Какие ресурсы и способности критичны для устойчивости и развития модели.';
